func label(for status: UploadStatus) -> String {
    switch status {
    case .waiting: return "Ждёт"
    case .uploading: return "Загружается"
    case .sent(let messageID): return "Сообщение # \(messageID)"
    case .failed(let reason): return "Ошибка: \(reason)"
    }
}

switch покрывает все случаи. Если появится новый статус, компилятор потребует решить, как его показать.

